from h import *
A = dict(id="A", levels=L1, kind="Web page", source="Marlow Wildlife Park website", title="Panda House opening day", body=[
 {"p": "Marlow Wildlife Park is proud to open its new Panda House on Saturday 14 June. Come and meet Lan and Bo, our two giant pandas."},
 {"p": "On the day you can:"},
 {"ul": ["watch the pandas eat their breakfast at 10:00", "ask a keeper your questions at 11:30", "have your face painted in the Bamboo Café", "pick up a free panda trail map at the gate"]},
 {"p": "Entry is free for everyone on opening day. Please arrive early, because the Panda House can only hold 200 people at a time."}])
B = dict(id="B", levels=L1, kind="Magazine article", source="Marlow Wildlife Park members' magazine", title="Behind the scenes at the Panda House", body=[
 {"p": "It took 14 months to build the new Panda House at Marlow Wildlife Park, and almost every detail was planned with the pandas in mind. Head keeper Priya Nair showed us around before the doors opened to the public."},
 {"h": "A home that feels like a forest"},
 {"p": "Each panda has its own indoor room, which is kept cool all year, and a large outdoor garden. Giant pandas come from the mountain forests of south-west China, so the garden has hills to climb, trees for shade and a small stream. \"Pandas are happiest when there is plenty to climb and somewhere shady to rest,\" says Priya."},
 {"h": "Bamboo, bamboo and more bamboo"},
 {"p": "Bamboo makes up almost all of a giant panda's diet, but it gives very little energy, so pandas spend much of the day eating. The park grows some of its own bamboo. The rest arrives fresh by lorry every week from a specialist grower (you can see the grower's farm on the map on page 4). Keepers check every delivery by hand and throw away any stalks that look dry."},
 {"h": "A keeper's day"},
 {"p": "Keepers start at 7:00 am by checking that both pandas are well. Next they clean the rooms and prepare the first feed. A team of six keepers will look after Lan and Bo, and a vet visits every month to check that they are healthy. They also hide small treats around the garden so that the pandas have to search for them. This is called enrichment, and it stops the pandas from getting bored."},
 {"p": "Visitors may find the pandas asleep. \"Please don't be disappointed,\" Priya adds. \"A sleeping panda is a healthy, relaxed panda.\""},
 {"p": "The Panda House is, without doubt, the best thing to happen to Marlow in years. Entry is free on opening day, but the park expects it to be very busy."}])
C = dict(id="C", levels=L1, kind="Blog post", source="The Day Out Diary blog", title="Our first visit to the Panda House", body=[
 {"p": "We went on opening day with my sister's kids, who are six and nine, and to be honest I'm still recovering! It was the busiest day I have seen at Marlow for ages."},
 {"h": "The good bits"},
 {"p": "The Panda House is gorgeous. The garden looks just like a real forest, and Bo was brilliant. He sat on a rock eating bamboo for ages. The kids loved watching him. The keeper talk at 11:30 was great as well. She told us that Lan and Bo spend most of the day eating, and my nine-year-old asked three questions in a row!"},
 {"h": "The not-so-good bits"},
 {"p": "We queued for nearly an hour, and by the time we got inside Lan was fast asleep in the corner. The Bamboo Café was packed, and I paid £4 for a tiny cup of tea. I was gutted!"},
 {"h": "My tips if you're going"},
 {"ul": ["Get there early, before the gates open if you can.", "Bring a packed lunch, because the café queue is huge.", "Check the feeding times on the website first, so you don't miss Bo at breakfast.", "Wear comfy shoes. You will walk loads."]},
 {"p": "Would I go again? Definitely, but on a quiet weekday!"}])

